create extension if not exists pgcrypto with schema extensions;
create schema if not exists private;
revoke all on schema private from public;
create type public.project_role as enum ('OWNER','ADMIN','FINANCE_MANAGER','APPROVER','MEMBER','VIEWER');
create table public.profiles(id uuid primary key references auth.users on delete cascade, full_name text not null default '',email text not null default '',avatar_url text,locale text not null default 'en-IN',timezone text not null default 'Asia/Kolkata',created_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),name text not null,code text not null,description text not null default '',currency text not null default 'INR' check(currency ~ '^[A-Z]{3}$'),status text not null default 'active' check(status in ('active','paused','closing','closed','archived')),start_date date,expected_end_date date,created_by uuid not null references auth.users,settings jsonb not null default '{}',closed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.project_members(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,user_id uuid not null references auth.users,role public.project_role not null default 'MEMBER',is_active boolean not null default true,joined_at timestamptz not null default now(),unique(project_id,user_id));
create table public.project_invites(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,email text not null,role public.project_role not null,token_hash text not null unique,expires_at timestamptz not null,invited_by uuid not null references auth.users,accepted_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,name text not null,kind text not null default 'expense',is_active boolean not null default true,unique(id,project_id),unique(project_id,name));
create table public.tags(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,name text not null,unique(project_id,name));
create table public.funding_sources(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,name text not null,type text not null default 'other',sanctioned_amount_minor bigint check(sanctioned_amount_minor>=0),currency text not null,notes text,unique(id,project_id));
create table public.financial_accounts(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,name text not null,account_type text not null check(account_type in ('CASH','BANK','WALLET','MEMBER_PAYABLE','ADVANCE','EXTERNAL','CLEARING','EXPENSE','FUNDING','VENDOR_PAYABLE','MEMBER_RECOVERY')),owner_user_id uuid references auth.users,currency text not null,is_active boolean not null default true,unique(id,project_id));
create unique index account_dimensions on public.financial_accounts(project_id,account_type,coalesce(owner_user_id,'00000000-0000-0000-0000-000000000000'::uuid)) where account_type not in ('CASH','BANK','WALLET');
create table public.financial_events(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,event_type text not null,status text not null default 'POSTED' check(status in ('POSTED','REVERSED')),event_date date not null default current_date,description text not null,reference_number text,created_by uuid not null references auth.users,posted_by uuid not null references auth.users,posted_at timestamptz not null default now(),reverses_event_id uuid unique,source_id uuid,metadata jsonb not null default '{}',idempotency_key uuid not null,command_hash text not null,unique(project_id,idempotency_key),unique(id,project_id),foreign key(reverses_event_id,project_id) references public.financial_events(id,project_id));
create table public.ledger_entries(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,financial_event_id uuid not null,account_id uuid not null,direction text not null check(direction in ('DEBIT','CREDIT')),amount_minor bigint not null check(amount_minor>0),currency text not null,category_id uuid,memo text,created_at timestamptz not null default now(),foreign key(financial_event_id,project_id) references public.financial_events(id,project_id),foreign key(account_id,project_id) references public.financial_accounts(id,project_id),foreign key(category_id,project_id) references public.categories(id,project_id));
create table public.vendors(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,name text not null,gstin text,contact_person text,email text,phone text,website text,address text,notes text,created_at timestamptz not null default now(),unique(id,project_id));
create table public.purchase_requests(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,requester_user_id uuid not null references auth.users,title text not null,reason text,estimated_minor bigint not null check(estimated_minor>0),category_id uuid,currency text not null,preferred_vendor_id uuid,desired_by_date date,status text not null default 'draft',approved_at timestamptz,created_at timestamptz not null default now(),unique(id,project_id),foreign key(preferred_vendor_id,project_id) references public.vendors(id,project_id));
create table public.purchases(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,vendor_id uuid,purchase_date date not null default current_date,invoice_number text,payment_method text,transaction_reference text,purpose text,tags text[] not null default '{}',status text not null default 'draft',subtotal_minor bigint not null default 0,tax_minor bigint not null default 0,shipping_minor bigint not null default 0,discount_minor bigint not null default 0,total_minor bigint not null check(total_minor>0),currency text not null,category_id uuid,purchased_by_user_id uuid not null references auth.users,notes text,linked_request_id uuid,bill_id uuid,financial_event_id uuid,created_by uuid not null references auth.users,version integer not null default 1,created_at timestamptz not null default now(),unique(id,project_id),check(total_minor=subtotal_minor+tax_minor+shipping_minor-discount_minor),foreign key(vendor_id,project_id) references public.vendors(id,project_id),foreign key(category_id,project_id) references public.categories(id,project_id),foreign key(linked_request_id,project_id) references public.purchase_requests(id,project_id),foreign key(financial_event_id,project_id) references public.financial_events(id,project_id));
create table public.purchase_items(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,purchase_id uuid not null,description text not null,sku text,quantity numeric(18,6) not null check(quantity>0),unit text not null default 'each',unit_price_minor bigint not null check(unit_price_minor>=0),tax_minor bigint not null default 0 check(tax_minor>=0),discount_minor bigint not null default 0 check(discount_minor>=0),line_total_minor bigint not null check(line_total_minor>=0),category_id uuid,mark_as_asset boolean not null default false,foreign key(purchase_id,project_id) references public.purchases(id,project_id),foreign key(category_id,project_id) references public.categories(id,project_id),unique(id,project_id));
create table public.bills(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,vendor_id uuid,invoice_number text,issue_date date not null default current_date,due_date date not null,status text not null default 'draft',subtotal_minor bigint not null,tax_minor bigint not null default 0,total_minor bigint not null check(total_minor>0),currency text not null,category_id uuid,notes text,linked_request_id uuid,created_by uuid not null references auth.users,financial_event_id uuid,created_at timestamptz not null default now(),unique(id,project_id),check(total_minor=subtotal_minor+tax_minor),foreign key(vendor_id,project_id) references public.vendors(id,project_id),foreign key(category_id,project_id) references public.categories(id,project_id),foreign key(financial_event_id,project_id) references public.financial_events(id,project_id));
alter table public.purchases add foreign key(bill_id,project_id) references public.bills(id,project_id);
create unique index purchase_invoice_unique on public.purchases(project_id,coalesce(vendor_id,'00000000-0000-0000-0000-000000000000'::uuid),lower(trim(invoice_number))) where invoice_number is not null and invoice_number<>'' and status<>'voided';
create unique index bill_invoice_unique on public.bills(project_id,coalesce(vendor_id,'00000000-0000-0000-0000-000000000000'::uuid),lower(trim(invoice_number))) where invoice_number is not null and invoice_number<>'' and status<>'cancelled';
create table public.advances(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,member_user_id uuid not null references auth.users,issued_minor bigint not null default 0,requested_minor bigint not null default 0 check(requested_minor>=0),currency text not null,status text not null default 'draft',purpose text not null,issued_at timestamptz,project_account_id uuid,financial_event_id uuid,created_by uuid not null references auth.users,created_at timestamptz not null default now(),unique(id,project_id),foreign key(project_account_id,project_id) references public.financial_accounts(id,project_id),foreign key(financial_event_id,project_id) references public.financial_events(id,project_id));
create table public.purchase_funding_allocations(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,purchase_id uuid not null,source_type text not null check(source_type in ('PROJECT_ACCOUNT','MEMBER','ADVANCE','EXTERNAL')),project_account_id uuid,member_user_id uuid references auth.users,advance_id uuid,funding_source_id uuid,amount_minor bigint not null check(amount_minor>0),currency text not null,foreign key(purchase_id,project_id) references public.purchases(id,project_id),foreign key(project_account_id,project_id) references public.financial_accounts(id,project_id),foreign key(advance_id,project_id) references public.advances(id,project_id),foreign key(funding_source_id,project_id) references public.funding_sources(id,project_id),check((source_type='PROJECT_ACCOUNT' and project_account_id is not null and member_user_id is null and advance_id is null and funding_source_id is null) or(source_type='MEMBER' and member_user_id is not null and project_account_id is null and advance_id is null and funding_source_id is null) or(source_type='ADVANCE' and advance_id is not null and project_account_id is null and member_user_id is null and funding_source_id is null) or(source_type='EXTERNAL' and funding_source_id is not null and project_account_id is null and member_user_id is null and advance_id is null)),unique(id,project_id));
create table public.reimbursement_claims(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,claimant_user_id uuid not null references auth.users,status text not null default 'draft',requested_minor bigint not null check(requested_minor>0),approved_minor bigint not null default 0,currency text not null,submitted_at timestamptz,approved_at timestamptz,notes text,created_at timestamptz not null default now(),unique(id,project_id));
create table public.reimbursement_claim_items(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,reimbursement_claim_id uuid not null,purchase_funding_allocation_id uuid not null,claimed_minor bigint not null check(claimed_minor>0),foreign key(reimbursement_claim_id,project_id) references public.reimbursement_claims(id,project_id),foreign key(purchase_funding_allocation_id,project_id) references public.purchase_funding_allocations(id,project_id),unique(reimbursement_claim_id,purchase_funding_allocation_id));
create table public.settlement_allocations(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,event_id uuid not null,source_allocation_id uuid not null,kind text not null check(kind in ('PAYMENT','REFUND','NONREIMBURSABLE','RECOVERY')),amount_minor bigint not null check(amount_minor>0),foreign key(event_id,project_id) references public.financial_events(id,project_id),foreign key(source_allocation_id,project_id) references public.purchase_funding_allocations(id,project_id));
create table public.bill_payments(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,bill_id uuid not null,project_account_id uuid not null,amount_minor bigint not null check(amount_minor>0),paid_at timestamptz not null default now(),method text,reference text,financial_event_id uuid not null,foreign key(bill_id,project_id) references public.bills(id,project_id),foreign key(project_account_id,project_id) references public.financial_accounts(id,project_id),foreign key(financial_event_id,project_id) references public.financial_events(id,project_id));
create table public.reimbursement_payments(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,reimbursement_claim_id uuid not null,project_account_id uuid not null,amount_minor bigint not null check(amount_minor>0),paid_at timestamptz not null default now(),payment_method text,reference text,financial_event_id uuid not null,paid_by_user_id uuid not null references auth.users,foreign key(reimbursement_claim_id,project_id) references public.reimbursement_claims(id,project_id),foreign key(project_account_id,project_id) references public.financial_accounts(id,project_id),foreign key(financial_event_id,project_id) references public.financial_events(id,project_id));
create table public.advance_returns(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,advance_id uuid not null,amount_minor bigint not null check(amount_minor>0),returned_at timestamptz not null default now(),financial_event_id uuid not null,reference text,foreign key(advance_id,project_id) references public.advances(id,project_id),foreign key(financial_event_id,project_id) references public.financial_events(id,project_id));
create table public.advance_expense_links(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,advance_id uuid not null,purchase_funding_allocation_id uuid not null unique,amount_minor bigint not null check(amount_minor>0),foreign key(advance_id,project_id) references public.advances(id,project_id),foreign key(purchase_funding_allocation_id,project_id) references public.purchase_funding_allocations(id,project_id));
create table public.funding_tranches(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,funding_source_id uuid not null,financial_event_id uuid not null,amount_minor bigint not null check(amount_minor>0),received_at date not null,foreign key(funding_source_id,project_id) references public.funding_sources(id,project_id),foreign key(financial_event_id,project_id) references public.financial_events(id,project_id));
create table public.refunds(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,purchase_id uuid,bill_id uuid,amount_minor bigint not null check(amount_minor>0),financial_event_id uuid not null,allocations jsonb not null,foreign key(purchase_id,project_id) references public.purchases(id,project_id),foreign key(bill_id,project_id) references public.bills(id,project_id),foreign key(financial_event_id,project_id) references public.financial_events(id,project_id));
create table public.budgets(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,name text not null,start_date date not null,end_date date not null,status text not null default 'active',unique(id,project_id),check(end_date>=start_date));
create table public.budget_lines(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,budget_id uuid not null,category_id uuid not null,planned_minor bigint not null check(planned_minor>=0),warning_percent integer not null default 80 check(warning_percent between 0 and 100),hard_stop boolean not null default false,foreign key(budget_id,project_id) references public.budgets(id,project_id),foreign key(category_id,project_id) references public.categories(id,project_id),unique(budget_id,category_id));
create table public.approval_policies(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,name text not null,entity_type text not null,is_active boolean not null default true,priority integer not null default 0,rule_json jsonb not null,unique(project_id,entity_type,priority));
create table public.approval_instances(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,entity_type text not null,entity_id uuid not null,policy_id uuid references public.approval_policies,approved_amount_minor bigint not null default 0,posted_event_id uuid,status text not null default 'pending',created_at timestamptz not null default now(),completed_at timestamptz,unique(id,project_id));
create table public.approval_steps(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,approval_instance_id uuid not null,step_order integer not null,approver_user_id uuid references auth.users,approver_role public.project_role,status text not null default 'pending',decided_by uuid references auth.users,decided_at timestamptz,comment text,foreign key(approval_instance_id,project_id) references public.approval_instances(id,project_id),unique(approval_instance_id,step_order));
create table public.purchase_request_items(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,request_id uuid not null,description text not null,quantity numeric not null check(quantity>0),estimated_unit_minor bigint not null,estimated_total_minor bigint not null,foreign key(request_id,project_id) references public.purchase_requests(id,project_id));
create table public.bill_items(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,bill_id uuid not null,description text not null,quantity numeric not null check(quantity>0),unit_price_minor bigint not null,tax_minor bigint not null default 0,discount_minor bigint not null default 0,line_total_minor bigint not null,foreign key(bill_id,project_id) references public.bills(id,project_id));
create table public.assets(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,purchase_item_id uuid unique,name text not null,serial_number text,asset_tag text,assigned_user_id uuid references auth.users,status text not null default 'available' check(status in ('available','assigned','repair','retired','lost')),purchase_value_minor bigint not null default 0,currency text not null,purchase_date date,warranty_expires_at date,location text,notes text,foreign key(purchase_item_id,project_id) references public.purchase_items(id,project_id),unique(project_id,asset_tag));
create table public.documents(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,entity_type text not null,entity_id uuid not null,document_type text not null,storage_bucket text not null default 'project-documents',storage_path text not null unique,original_filename text not null,mime_type text not null,size_bytes bigint not null check(size_bytes between 1 and 20971520),uploaded_by uuid not null references auth.users,status text not null default 'pending',created_at timestamptz not null default now(),checksum text);
create table public.comments(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,entity_type text not null,entity_id uuid not null,author_user_id uuid not null references auth.users,body text not null check(length(body) between 1 and 10000),created_at timestamptz not null default now(),edited_at timestamptz,deleted_at timestamptz);
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,project_id uuid references public.projects,type text not null,title text not null,body text,entity_type text,entity_id uuid,read_at timestamptz,created_at timestamptz not null default now(),dedupe_key text unique);
create table public.document_templates(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects,template_type text not null,name text not null,subject_template text,body_template text not null,is_system_template boolean not null default false,created_by uuid references auth.users,updated_at timestamptz not null default now());
create table public.generated_documents(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,template_id uuid not null references public.document_templates,generated_by uuid not null references auth.users,entity_type text not null,entity_id uuid not null,reference_number text not null,rendered_html text not null,snapshot jsonb not null,storage_document_id uuid references public.documents,generated_at timestamptz not null default now(),unique(project_id,reference_number));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects,actor_user_id uuid references auth.users,action text not null,entity_type text not null,entity_id uuid,before_data jsonb,after_data jsonb,reason text,correlation_id uuid,created_at timestamptz not null default now());
create table public.activity_events(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,actor_user_id uuid references auth.users,type text not null,entity_type text not null,entity_id uuid,summary text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.recurring_expense_templates(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,vendor_id uuid,description text not null,amount_minor bigint,currency text not null,category_id uuid,recurrence_rule text not null check(recurrence_rule in ('monthly','weekly','yearly')),next_due_date date not null,active boolean not null default true,foreign key(vendor_id,project_id) references public.vendors(id,project_id),foreign key(category_id,project_id) references public.categories(id,project_id));
do $$ declare t text; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t); if exists(select 1 from information_schema.columns where table_schema='public' and table_name=t and column_name='project_id') then execute format('create index on public.%I(project_id)',t); end if; end loop; end $$;
create index on public.financial_events(project_id,event_date,posted_at);
create index on public.ledger_entries(project_id,account_id);
create index on public.purchases(project_id,purchase_date,status);
create index on public.bills(project_id,due_date,status);

alter table public.purchase_requests add foreign key(category_id,project_id) references public.categories(id,project_id);
alter table public.bills add foreign key(linked_request_id,project_id) references public.purchase_requests(id,project_id);

alter table public.approval_instances add foreign key(posted_event_id,project_id) references public.financial_events(id,project_id);

alter table public.financial_events add column corrects_event_id uuid;
alter table public.financial_events add foreign key(corrects_event_id,project_id) references public.financial_events(id,project_id);
create unique index one_corrected_replacement on public.financial_events(corrects_event_id) where corrects_event_id is not null;
alter table public.purchases add column corrects_event_id uuid;
alter table public.purchases add foreign key(corrects_event_id,project_id) references public.financial_events(id,project_id);
alter table public.bills add column corrects_event_id uuid;
alter table public.bills add foreign key(corrects_event_id,project_id) references public.financial_events(id,project_id);
